from substrateinterface import SubstrateInterface
from scalecodec.base import ScaleBytes
import traceback

substrate = SubstrateInterface(
    url="wss://rpc.polkadot.io",
    type_registry_preset="polkadot"
)

def decode_note_preimage(hex_bytes: str):
    if hex_bytes.startswith("0x"):
        hex_bytes = hex_bytes[2:]

    try:
        scale_data = ScaleBytes("0x" + hex_bytes)
        call = substrate.create_scale_object("Call", data=scale_data)
        import pdb; pdb.set_trace()
        call.decode()
        return call.value  # This gives you the full method, section, and arguments
    except Exception:
        traceback.print_exc()
        return None
preimage_hex = ""

decoded = decode_note_preimage(preimage_hex)

print(decoded)
